from pathlib import Path
import json,statistics
E=Path(__file__).resolve().parent
rows=json.loads((E/'capture-validation.json').read_text()); assert len(rows)==12,len(rows)
summary={}
for size in [64,65537]:
 r=[x for x in rows if x['result']['payload_bytes']==size]
 d={v:{k:statistics.median(x['result'][k] for x in r if x['server']==v) for k in ['calls_per_second','p99_ms']} for v in ['base','capture']}
 d['changes']={k:100*(d['capture'][k]/d['base'][k]-1) for k in d['base']};d['pairs']=[]
 for i in range(1,4):
  a,b=[next(x['result'] for x in r if x['label']==f'capture-budget-{size}-{i}-{v}') for v in ['base','capture']];d['pairs'].append({k:100*(b[k]/a[k]-1) for k in d['base']})
 d['calls']=sum(x['result']['calls'] for x in r);summary[str(size)]=d
(E/'validation-summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))

