package rpc

import (
 "context"
 "testing"
)

// BenchmarkQueueWatcher isolates the actual registration/detachment methods.
// Fresh contexts match per-request inbound tracking; reuse is diagnostic only.
func BenchmarkQueueWatcher(b *testing.B) {
 for _, mode:=range []string{"fresh_context_only","fresh_context_watch","reused_context_watch"} {
  b.Run(mode,func(b *testing.B){
   root,cancelRoot:=context.WithCancel(context.Background()); defer cancelRoot()
   s:=&Service{ctx:root}
   ctx,cancel:=context.WithCancel(root);defer cancel()
   e:=&requestEntry{serviceTask:serviceTask{service:s,req:Request{Context:ctx}}}
   // Warm root child storage, and the diagnostic reused context's storage.
   e.watchQueue(s);e.stopQueueWatch()
   b.ReportAllocs();b.ResetTimer()
   for i:=0;i<b.N;i++ {
    if mode!="reused_context_watch" {ctx,cancel=context.WithCancel(root);e.req.Context=ctx}
    if e.req.Context.Err()!=nil {b.Fatal("unexpected cancellation")}
    s.mu.Lock()
    if mode!="fresh_context_only" {e.watchQueue(s);e.stopQueueWatch()}
    s.mu.Unlock()
    if mode!="reused_context_watch" {cancel()}
   }
  })
 }
}
